#include "../src/gpu_batch_profile.hpp"
#include <dxgi1_4.h>
#include <cstdio>
#include <stdexcept>
using Microsoft::WRL::ComPtr;
void check(HRESULT h){if(FAILED(h))throw std::runtime_error("D3D fixture failed");}
int main(){try{ComPtr<IDXGIFactory4> factory;check(CreateDXGIFactory1(IID_PPV_ARGS(&factory)));ComPtr<IDXGIAdapter> warp;check(factory->EnumWarpAdapter(IID_PPV_ARGS(&warp)));ComPtr<ID3D12Device> device;check(D3D12CreateDevice(warp.Get(),D3D_FEATURE_LEVEL_11_0,IID_PPV_ARGS(&device)));ComPtr<ID3D12CommandQueue> q;D3D12_COMMAND_QUEUE_DESC qd{};check(device->CreateCommandQueue(&qd,IID_PPV_ARGS(&q)));ComPtr<ID3D12CommandAllocator> a;check(device->CreateCommandAllocator(D3D12_COMMAND_LIST_TYPE_DIRECT,IID_PPV_ARGS(&a)));ComPtr<ID3D12GraphicsCommandList> c;check(device->CreateCommandList(0,D3D12_COMMAND_LIST_TYPE_DIRECT,a.Get(),nullptr,IID_PPV_ARGS(&c)));check(c->Close());ComPtr<ID3D12Fence> f;check(device->CreateFence(0,D3D12_FENCE_FLAG_NONE,IID_PPV_ARGS(&f)));HANDLE event=CreateEvent(nullptr,FALSE,FALSE,nullptr);if(!event)throw std::runtime_error("event failed");gpuBatchProfile::Timer timer;
for(unsigned i=1;i<=16;++i){check(a->Reset());check(c->Reset(a.Get(),nullptr));if(!timer.begin(device.Get(),c.Get()))throw std::runtime_error("timer unavailable");timer.end(c.Get());check(c->Close());ID3D12CommandList* lists[]={c.Get()};q->ExecuteCommandLists(1,lists);check(q->Signal(f.Get(),i));if(f->GetCompletedValue()<i){check(f->SetEventOnCompletion(i,event));if(WaitForSingleObject(event,10000)!=WAIT_OBJECT_0)throw std::runtime_error("fence failed");}if(!timer.completed(q.Get())||timer.completed(q.Get()))throw std::runtime_error("one read per completed batch required");}
CloseHandle(event);if(timer.samples!=16||timer.failures||timer.totalMilliseconds<0)throw std::runtime_error("invalid samples");timer.resetTotals();if(timer.samples||timer.failures||timer.totalMilliseconds)throw std::runtime_error("reset failed");puts("PASS: 16 actual WARP timestamp/resolve/readback cycles, allocator reuse after completion, one read per batch and reset. No game or VR performance claim.");return 0;}catch(const std::exception& e){puts(e.what());return 1;}}
